    pub(crate) groups: Vec<OpacityGroup>,
    pub(crate) filters: Vec<Filter>,
    pub(crate) filter_primitives: Vec<FilterPrimitive>,
    pub(crate) masks: Vec<Mask>,
    pub(crate) patterns: Vec<Pattern>,
    pub(crate) fill_paints: Vec<Paint>,
