        transforms: Option<&'b [TransformFrame]>,
        clips: Option<&'b [Clip]>,
    ) -> SceneView<'b> {
        let mut view: SceneView<'b> = *self;
        if let Some(v) = edges {
            view.edges = v;
        }
        if let Some(v) = colors {
            view.edge_colors = v;
        }
        if let Some(v) = shapes {
            view.shapes = v;
        }
        if let Some(v) = fills {
            view.fill_paints = v;
        }
        if let Some(v) = strokes {
            view.stroke_paints = v;
