use std::sync::atomic::{AtomicU64, Ordering};
static NEXT_OWNER: AtomicU64 = AtomicU64::new(1);

/// A scene-local append checkpoint. Rollback invalidates all marks for that scene.
/// It does not rewind independent child scenes, work charges or allocation history.
#[derive(Debug)]
pub struct BuildMark {
    pub(crate) scene: SceneId,
    pub(crate) epoch: u64,
    pub(crate) image_pixels: usize,
    pub(crate) lengths: [usize; 26],
}
/// Exact per-edge colors and parser-owned metadata; no synthetic color conversion.
#[derive(Debug)]
pub struct ShapeInput {
    pub shape: Shape,
    pub path: vexel_svg_path::PathDocument,
    pub edge_colors: Vec<[u8; 4]>,
}
#[derive(Debug)]
pub struct SceneBuilder {
    pub(crate) owner: u64,
    pub(crate) source: SourceOwner,
    pub(crate) generation: u64,
    pub(crate) scenes: Vec<SceneData>,
    pub(crate) animation: OwnedAnimation,
    pub(crate) ignored: [Ignored; 4],
    pub(crate) stats: MemoryStats,
    pub(crate) limits: Limits,
    pub(crate) drafts: [Option<crate::draft::ActiveDraft>; 64],
    pub(crate) draft_depth: usize,
    next_serial: u64,
    root: SceneId,
}

macro_rules! room {
    ($self:ident,$index:expr,$field:ident,$extra:expr,$cap:expr,$pending:expr) => {{
        let pending = $pending;
        let current = add($self.stats.live_bytes, pending)?;
        let available = $self
            .limits
            .reserved_bytes
            .checked_sub(current)
            .ok_or_else(|| limit(LimitKind::ReservedBytes))?;
        // Check all counters before the mutating reserve can transfer old values.
        let history_room = usize::MAX - $self.stats.total_allocated_bytes;
        let available = available.min(history_room);
        if $self.stats.allocation_count == usize::MAX {
            return Err(arithmetic());
        }
        let (new, old) = reserve(&mut $self.scenes[$index].$field, $extra, $cap, available)?;
        if new != 0 {
            $self.stats.peak_live_bytes = $self.stats.peak_live_bytes.max(add(current, new)?);
            $self.stats.total_allocated_bytes = add($self.stats.total_allocated_bytes, new)?;
            $self.stats.allocation_count += 1;
            $self.stats.live_bytes = add($self.stats.live_bytes - old, new)?;
        }
    }};
}
pub(crate) use room;

impl SceneBuilder {
    pub fn new(
        source: SourceOwner,
        animation: OwnedAnimation,
        generation: u64,
        viewport: Viewport,
        limits: Limits,
    ) -> Result<Self> {
        let limits = limits.effective();
        if !std::sync::Arc::ptr_eq(&source, animation.source_owner()) {
            return Err(invalid(0));
        }
        if source.len() > limits.source_bytes {
            return Err(limit(LimitKind::SourceBytes));
        }
        crate::validate::viewport(viewport)?;
        let live = animation.storage_bytes().ok_or_else(arithmetic)?;
        if live > limits.reserved_bytes {
            return Err(limit(LimitKind::ReservedBytes));
        }
        let owner = NEXT_OWNER
            .try_update(Ordering::Relaxed, Ordering::Relaxed, |v| v.checked_add(1))
            .map_err(|_| arithmetic())?;
        let root = SceneId {
            owner,
            slot: 0,
            serial: 1,
        };
        let mut value = Self {
            owner,
            source,
            generation,
            scenes: Vec::new(),
            animation,
            ignored: [Ignored::default(); 4],
            stats: MemoryStats {
                source_bytes: live,
                live_bytes: live,
                peak_live_bytes: live,
                total_allocated_bytes: 0,
                allocation_count: 0,
            },
            limits,
            drafts: [None; 64],
            draft_depth: 0,
            next_serial: 1,
            root,
        };
        value.stats.source_bytes = value.source.capacity();
        let actual = value.reserve_scene()?;
        value.scenes.push(SceneData::new(actual.serial, viewport));
        value.root = actual;
        Ok(value)
    }
    fn reserve_scene(&mut self) -> Result<SceneId> {
        let serial = self.serial()?;
        let available = self
            .limits
            .reserved_bytes
            .checked_sub(self.stats.live_bytes)
            .ok_or_else(|| limit(LimitKind::ReservedBytes))?;
        if self.stats.allocation_count == usize::MAX {
            return Err(arithmetic());
        }
        let (new, old) = reserve(
            &mut self.scenes,
            1,
            self.limits.scenes,
            available.min(usize::MAX - self.stats.total_allocated_bytes),
        )?;
        if new != 0 {
            self.stats.peak_live_bytes = self
                .stats
                .peak_live_bytes
                .max(add(self.stats.live_bytes, new)?);
            self.stats.live_bytes = add(self.stats.live_bytes - old, new)?;
            self.stats.total_allocated_bytes = add(self.stats.total_allocated_bytes, new)?;
            self.stats.allocation_count += 1;
        }
        Ok(SceneId {
            owner: self.owner,
            slot: self.scenes.len() as u32,
            serial,
        })
    }
    pub(crate) fn serial(&mut self) -> Result<u64> {
        let serial = self.next_serial;
        self.next_serial = self.next_serial.checked_add(1).ok_or_else(arithmetic)?;
        Ok(serial)
    }
    pub(crate) fn index(&self, id: SceneId) -> Result<usize> {
        let scene = self.scenes.get(id.index()).ok_or_else(|| invalid(0))?;
        if id.owner != self.owner || id.serial != scene.serial {
            return Err(invalid(0));
        }
        Ok(id.index())
    }
    pub(crate) fn writable(&self, id: SceneId) -> Result<usize> {
        let index = self.index(id)?;
        if self.scenes[index].sealed || self.active_draft().is_some_and(|draft| draft.scene != id) {
            return Err(invalid(0));
        }
        Ok(index)
    }
    pub fn source_owner(&self) -> &SourceOwner {
        &self.source
    }
    pub fn root_id(&self) -> SceneId {
        self.root
    }
    pub fn scene(&self, id: SceneId) -> Result<SceneView<'_>> {
        let i = self.index(id)?;
        Ok(self.scenes[i].view(
            self.owner,
            i,
            &self.scenes,
            &self.source,
            self.animation.view(),
            self.ignored,
        ))
    }
    pub fn memory_stats(&self) -> MemoryStats {
        self.stats
    }
    pub fn new_scene(&mut self, viewport: Viewport) -> Result<SceneId> {
        crate::validate::viewport(viewport)?;
        let id = self.reserve_scene()?;
        self.scenes.push(SceneData::new(id.serial, viewport));
        Ok(id)
    }
    pub fn mark(&self, scene: SceneId) -> Result<BuildMark> {
        if self.draft_depth != 0 {
            return Err(invalid(0));
        }
        self.checkpoint_internal(scene)
    }
    pub(crate) fn checkpoint_internal(&self, scene: SceneId) -> Result<BuildMark> {
        self.writable(scene)?;
        self.checkpoint_unrestricted(scene)
    }
    pub(crate) fn checkpoint_unrestricted(&self, scene: SceneId) -> Result<BuildMark> {
        let i = self.index(scene)?;
        Ok(BuildMark {
            scene,
            epoch: self.scenes[i].epoch,
            image_pixels: self.scenes[i].image_pixels,
            lengths: self.scenes[i].lengths(),
        })
    }
    pub fn rollback(&mut self, mark: BuildMark) -> Result<()> {
        if self.draft_depth != 0 {
            return Err(invalid(0));
        }
        self.rollback_internal(mark)
    }

#include "shape.h"
#include "shape_render.h"
#include "shape_render_internal.h"
#include "shape_render_preflight.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CANVAS_W 1056U
#define CANVAS_H 1000U
#define OLD_BUDGET 200000000ULL
/* Measured on 1056x1000 (budget 382,452,224): 1,000 teeth need 365,760,771 work
 * units (over the old 200M, inside the new budget); 1,100 teeth exceed it. */
#define TEETH_INSIDE 1000U
#define TEETH_OVER 1100U

static int failures;

static void check(bool condition, const char *message)
{
    if (condition) return;
    (void)fprintf(stderr, "FAIL: %s\n", message);
    failures++;
}

/* A gradient-filled zigzag whose every edge spans all rows, so the active-edge
 * count, and with it the raster work, grows linearly with `teeth`. */
static char *make_source(unsigned teeth)
{
    size_t capacity = 512U + (size_t)teeth * 24U;
    char *text = malloc(capacity);
    if (text == NULL) return NULL;
    size_t used = (size_t)snprintf(text, capacity,
        "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"%u\" height=\"%u\" "
        "viewBox=\"0 0 %u %u\"><defs><linearGradient id=\"g\">"
        "<stop offset=\"0\" stop-color=\"#f00\"/><stop offset=\"1\" "
        "stop-color=\"#00f\"/></linearGradient></defs>"
        "<path fill=\"url(#g)\" d=\"M0 0", CANVAS_W, CANVAS_H, CANVAS_W, CANVAS_H);
    for (unsigned tooth = 0U; tooth < teeth && used + 24U < capacity; tooth++)
        used += (size_t)snprintf(text + used, capacity - used, " L%.3f %u",
            (double)(tooth + 1U) * (double)CANVAS_W / (double)teeth,
            tooth % 2U == 0U ? CANVAS_H : 0U);
    (void)snprintf(text + used, capacity - used, " Z\"/></svg>");
    return text;
}

static svg_shape_error render(unsigned teeth, uint64_t *work_units,
                                       size_t *offset)
{
    char *source = make_source(teeth);
    svg_shape_document document = {0};
    svg_shape_diagnostic diagnostic = {0};
    if (source == NULL) return SVG_SHAPE_ERROR_OOM;
    svg_shape_error category = svg_shape_decode(
        (base_bytes){(const uint8_t *)source, strlen(source)}, &document,
        &diagnostic);
    free(source);
    if (category != SVG_SHAPE_ERROR_NONE) return category;
    raster_tile tile = {0};
    raster_shape_work_stats stats = {0};
    bool rendered = raster_shape_render_with_stats(&document, &tile,
                                                   &diagnostic, &stats);
    if (work_units != NULL) *work_units = stats.total_work;
    if (offset != NULL) *offset = diagnostic.offset;
    if (rendered) raster_tile_destroy(&tile);
    svg_shape_document_destroy(&document);
    return rendered ? SVG_SHAPE_ERROR_NONE : diagnostic.category;
}

int main(void)
{
    size_t canvas_budget = raster_preflight_work_budget(CANVAS_W, CANVAS_H);
    check(raster_preflight_work_budget(1U, 1U) == OLD_BUDGET,
          "small canvas keeps the 200M budget");
    check(raster_preflight_work_budget(1024U, 1024U) == OLD_BUDGET,
          "1024x1024 keeps the 200M budget");
    check(canvas_budget == 382452224ULL, "1056x1000 gets 200M + 7424 * 24576");
    check(raster_preflight_work_budget(1600U, 1000U) == 13751796224ULL,
          "1600x1000 gets 13,751,796,224");
    check(raster_preflight_work_budget(8192U, 8192U) == 16000000000ULL &&
          raster_preflight_work_budget(UINT32_MAX, UINT32_MAX) ==
          16000000000ULL, "budget is capped at 16e9");

    uint64_t inside_work = 0U, over_work = 0U;
    size_t offset = 1U;
    svg_shape_error inside = render(TEETH_INSIDE, &inside_work, &offset);
    check(inside == SVG_SHAPE_ERROR_NONE, "document inside the new budget renders");
    check(inside_work > OLD_BUDGET && inside_work <= canvas_budget,
          "inside document needs more than the old fixed budget and fits the new one");
    offset = 1U;
    svg_shape_error over = render(TEETH_OVER, &over_work, &offset);
    check(over == SVG_SHAPE_ERROR_LIMIT && offset == 0U,
          "document over the new budget fails with LIMIT at offset 0");
    (void)printf("inside work=%llu budget=%zu over=%d\n",
                 (unsigned long long)inside_work, canvas_budget, (int)over);
    return failures == 0 ? 0 : 1;
}

